   652      metrics->height       = p[0];
   653      metrics->width        = p[1];
   654      metrics->horiBearingX = (FT_Char)p[2];
   655      metrics->horiBearingY = (FT_Char)p[3];
   656      metrics->horiAdvance  = p[4];
   657
   658      p += 5;
   659      if ( big )
